INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Mehrlinienorganisation immer chaotisch ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Struktur effizient"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Mehrlinienorganisation in einer IT-Firma einführe?', 3, '[{"text": "Rollenklarheit", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Mehrlinienorganisation in der IT?', 5, '[{"text": "Mehrere Vorgesetzte", "correct": true, "because": "Doppelte Berichtslinien"}, {"text": "Hierarchische Struktur", "correct": true, "because": "Kombiniert Ebenen"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Mehrlinienorganisation fördert Koordination. b) Sie hat keine Hierarchie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hat Hierarchie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Mehrlinienorganisation für eine IT-Firma plane?', 4, '[{"text": "Kommunikationswege", "correct": false, "because": "Sichern Ablauf"}, {"text": "Verantwortlichkeiten", "correct": false, "because": "Vermeiden Konflikte"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Mehrlinienorganisation immer nur zwei Vorgesetzte hat?', 2, '[{"text": "Nein", "correct": true, "because": "Kann mehrere haben"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Mehrlinienorganisation in der IT?', 3, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Nutzt Teams optimal"}, {"text": "Schnellste Struktur", "correct": false, "because": "Effektivität zählt"}, {"text": "Weniger Hierarchie", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Mehrlinienorganisation in der IT?', 5, '[{"text": "Spezialisierung", "correct": true, "because": "Nutzt Expertise"}, {"text": "Koordination", "correct": true, "because": "Verbindet Bereiche"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Mehrlinienorganisation verbessert Zusammenarbeit. b) Sie ist immer ineffizient. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht zwangsläufig ineffizient"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Mehrlinienorganisation in der IT einzuführen?', 4, '[{"text": "Rollenverteilung", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Kommunikationsplan", "correct": false, "because": "Sichert Ablauf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Mehrlinienorganisation immer komplexer als eine Einlinienorganisation?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrere Berichtslinien"}, {"text": "Nein", "correct": false, "because": "Mit Planung effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Mehrlinienorganisation in der IT?', 4, '[{"text": "Rollenkonflikte", "correct": true, "because": "Doppelte Vorgesetzte"}, {"text": "Komplexität", "correct": true, "because": "Erhöht Koordination"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Mehrlinienorganisation nur für große IT-Firmen geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Mehrlinienorganisation effektiv zu gestalten?', 3, '[{"text": "Klare Kommunikation", "correct": true, "because": "Sichert Koordination"}, {"text": "Schnellste Einführung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Bunte Organigramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Mehrlinienorganisation nutzt mehrere Vorgesetzte. b) Sie ist immer hierarchiefrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hat Hierarchie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einer Mehrlinienorganisation?', 5, '[{"text": "Projektmanagement", "correct": true, "because": "Koordiniert Teams"}, {"text": "Kommunikationswege", "correct": true, "because": "Sichern Ablauf"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Mehrlinienorganisation für eine IT-Firma plane?', 3, '[{"text": "Rollenklarheit", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Teamkoordination", "correct": false, "because": "Sichert Effizienz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Organisationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat eine Mehrlinienorganisation immer nur eine Berichtslinie?', 3, '[{"text": "Nein", "correct": true, "because": "Mehrere Linien"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Mehrlinienorganisation nur für IT geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Branchen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für eine Mehrlinienorganisation?', 4, '[{"text": "Klare Verantwortlichkeiten", "correct": true, "because": "Sichert Effizienz"}, {"text": "Schnellste Einführung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
